bClient(\r\n    containerName: string,\r\n    blobName: string\r\n  ): BlockBlobClient {\r\n    return this.getContainerClient(containerName).getBlockBlobClient(blobName);\r\n  }\r\n\r\n  /**\r\n   * Ensure the container exists (creates it if not).\r\n   */\r\n  async ensureContainer(containerName: string): Promise\u003cvoid\u003e {\r\n    const container = this.getContainerClient(containerName);\r\n    await container.createIfNotExists();\r\n  }\r\n\r\n  /**\r\n   * Upload a file using streaming so the entire file is never loaded into\r\n   * memory at once. Supports optional metadata and blob index tags.\r\n   */\r\n  async uploadFile(\r\n    containerName: string,\r\n    blobName: string,\r\n    filePath: string,\r\n    options?: UploadOptions\r\n  ): Promise\u003cBlobUploadCommonResponse\u003e {\r\n    const blockBlob = this.getBlockBlobClient(containerName, blobName);\r\n    const stream = fs.createReadStream(filePath);\r\n\r\n    // 4 MiB buffer size, 5 concurrent buffers — keeps memory bounded even\r\n    // for multi-gigabyte files.\r\n    const bufferSize = 4 * 1024 * 1024;\r\n    const maxConcurrency = 5;\r\n\r\n    return blockBlob.uploadStream(stream, bufferSize, maxConcurrency, {\r\n      metadata: options?.metadata,\r\n      tags: options?.tags,\r\n      blobHTTPHeaders: {\r\n        blobContentType: options?.contentType ?? \"application/octet-stream\",\r\n      },\r\n    });\r\n  }\r\n\r\n  /**\r\n   * Upload content from a string or Buffer using streaming.\r\n   */\r\n  async uploadContent(\r\n    containerName: string,\r\n    blobName: string,\r\n    content: string | Buffer,\r\n    options?: UploadOptions\r\n  ): Promise\u003cBlobUploadCommonResponse\u003e {\r\n    const blockBlob = this.getBlockBlobClient(containerName, blobName);\r\n    const buf = Buffer.isBuffer(content) ? content : Buffer.from(content);\r\n    const stream = Readable.from(buf);\r\n\r\n    const bufferSize = 4 * 1024 * 1024;\r\n    const maxConcurrency = 5;\r\n\r\n    return blockBlob.uploadStream(stream, bufferSize, maxConcurrency, {\r\n      metadata: options?.metadata,\r\n      tags: options?.tags,\r\n      blobHTTPHeaders: {\r\n        blobContentType: options?.contentType ?? \"application/octet-stream\",\r\n      },\r\n    });\r\n  }\r\n\r\n  /**\r\n   * Download a blob and return its content as a UTF-8 string.\r\n   */\r\n  async download(\r\n    containerName: string,\r\n    blobName: string\r\n  ): Promise\u003cDownloadResult\u003e {\r\n    const blockBlob = this.getBlockBlobClient(containerName, blobName);\r\n    const response = await blockBlob.download(0);\r\n\r\n    const body = response.readableStreamBody;\r\n    if (!body) {\r\n      throw new Error(\"Download response did not contain a readable stream.\");\r\n    }\r\n\r\n    const chunks: Buffer[] = [];\r\n    for await (const chunk of body) {\r\n      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));\r\n    }\r\n    const buffer = Buffer.concat(chunks);\r\n\r\n    return {\r\n      content: buffer.toString(\"utf-8\"),\r\n      contentLength: buffer.length,\r\n      metadata: response.metadata,\r\n    };\r\n  }\r\n\r\n  /**\r\n   * List all blobs in a container.\r\n   */\r\n  async listBlobs(containerName: string): Promise\u003cBlobItem[]\u003e {\r\n    const container = this.getContainerClient(containerName);\r\n    const blobs: BlobItem[] = [];\r\n    for await (const blob of container.listBlobsFlat({ includeMetadata: true })) {\r\n      blobs.push(blob);\r\n    }\r\n    return blobs;\r\n  }\r\n\r\n  /**\r\n   * Delete a blob. Returns silently if the blob does not exist.\r\n   */\r\n  async delete(\r\n    containerName: string,\r\n    blobName: string\r\n  ): Promise\u003cBlobDeleteResponse\u003e {\r\n    const blockBlob = this.getBlockBlobClient(containerName, blobName);\r\n    return blockBlob.deleteIfExists({ deleteSnapshots: \"include\" });\r\n  }\r\n\r\n  /**\r\n   * Acquire a lease on a blob, perform a write, then release the lease.\r\n   * This prevents concurrent writers from overwriting each other's changes.\r\n   *\r\n   * @param leaseDurationSec  Lease duration in seconds (15–60, or -1 for infinite).\r\n   */\r\n  async uploadWithLease(\r\n    containerName: string,\r\n    blobName: string,\r\n    content: string | Buffer,\r\n    options?: UploadOptions \u0026 { leaseDurationSec?: number }\r\n  ): Promise\u003cBlobUploadCommonResponse\u003e {\r\n    const blockBlob = this.getBlockBlobClient(containerName, blobName);\r\n    const leaseClient = blockBlob.getBlobLeaseClient();\r\n    const leaseDuration = options?.leaseDurationSec ?? 30;\r\n\r\n    const lease = await leaseClient.acquireLease(leaseDuration);\r\n    const leaseId = lease.leaseId!;\r\n\r\n    try {\r\n      const buf = Buffer.isBuffer(content) ? content : Buffer.from(content);\r\n      const stream = Readable.from(buf);\r\n\r\n      const bufferSize = 4 * 1024 * 1024;\r\n      const maxConcurrency = 5;\r\n\r\n      return await blockBlob.uploadStream(stream, bufferSize, maxConcurrency, {\r\n        metadata: options?.metadata,\r\n        tags: options?.tags,\r\n        blobHTTPHeaders: {\r\n          blobContentType: options?.contentType ?? \"application/octet-stream\",\r\n        },\r\n        conditions: { leaseId },\r\n      });\r\n    } finally {\r\n      await leaseClient.releaseLease();\r\n    }\r\n  }\r\n}\r\n\n```\n\n### src\\config.ts\n```\nimport { DefaultAzureCredential } from \"@azure/identity\";\r\nimport {\r\n  BlobServiceClient,\r\n  StorageRetryPolicyType,\r\n  StorageRetryOptions,\r\n} from \"@azure/storage-blob\";\r\nimport { setLogLevel, AzureLogger } from \"@azure/logger\";\r\n\r\nexport interface BlobStorageConfig {\r\n  /** Storage account blob endpoint, e.g. https://\u003caccount\u003e.blob.core.windows.net */\r\n  storageEndpoint: string;\r\n  /** Maximum number of retry attempts (default: 3) */\r\n  maxRetries?: number;\r\n  /** Maximum delay between retries in ms (default: 4000) */\r\n  maxRetryDelayMs?: number;\r\n  /** Initial retry delay in ms (default: 1000) */\r\n  retryDelayMs?: number;\r\n  /**\r\n   * Azure SDK log level for debugging.\r\n   * One of: verbose, info, warning, error (default: warning)\r\n   */\r\n  logLevel?: \"verbose\" | \"info\" | \"warning\" | \"error\";\r\n}\r\n\r\n/**\r\n * Build a BlobServiceClient using DefaultAzureCredential (managed identity /\r\n * Azure CLI / environment creds — no connection strings or account keys).\r\n */\r\nexport function createBlobServiceClient(\r\n  config?: Partial\u003cBlobStorageConfig\u003e\r\n): BlobServiceClient {\r\n  const storageEndpoint =\r\n    config?.storageEndpoint ??\r\n    process.env.AZURE_STORAGE_ENDPOINT ??\r\n    \"\";\r\n\r\n  if (!storageEndpoint) {\r\n    throw new Error(\r\n      \"Storage endpoint is required. Set AZURE_STORAGE_ENDPOINT or pass storageEndpoint in config.\"\r\n    );\r\n  }\r\n\r\n  const logLevel = config?.logLevel ?? \"warning\";\r\n  setLogLevel(logLevel);\r\n  AzureLogger.log = (...args) =\u003e {\r\n    console.log(\"[azure-sdk]\", ...args);\r\n  };\r\n\r\n  const retryOptions: StorageRetryOptions = {\r\n    retryPolicyType: StorageRetryPolicyType.EXPONENTIAL,\r\n    maxTries: config?.maxRetries ?? 3,\r\n    retryDelayInMs: config?.retryDelayMs ?? 1000,\r\n    maxRetryDelayInMs: config?.maxRetryDelayMs ?? 4000,\r\n  };\r\n\r\n  const credential = new DefaultAzureCredential();\r\n\r\n  return new BlobServiceClient(storageEndpoint, credential, {\r\n    retryOptions,\r\n  });\r\n}\r\n\n```\n\n### src\\main.ts\n```\nimport * as fs from \"fs\";\r\nimport * as path from \"path\";\r\nimport * as os from \"os\";\r\nimport { createBlobServiceClient } from \"./config\";\r\nimport { BlobStorageService } from \"./blobService\";\r\n\r\nconst CONTAINER_NAME = \"demo-container\";\r\nconst BLOB_NAME = \"sample.txt\";\r\n\r\nasync function main(): Promise\u003cvoid\u003e {\r\n  console.log(\"=== Azure Blob Storage Manager Demo ===\\n\");\r\n\r\n  // 1. Initialise client \u0026 service\r\n  const serviceClient = createBlobServiceClient();\r\n  const blobService = new BlobStorageService(serviceClient);\r\n\r\n  // Ensure the container exists\r\n  await blobService.ensureContainer(CONTAINER_NAME);\r\n  console.log(`✔ Container \"${CONTAINER_NAME}\" is ready.\\n`);\r\n\r\n  // 2. Create a sample file and upload it with metadata + index tags\r\n  const sampleDir = fs.mkdtempSync(path.join(os.tmpdir(), \"blob-demo-\"));\r\n  const sampleFile = path.join(sampleDir, \"sample.txt\");\r\n  fs.writeFileSync(sampleFile, \"Hello from the Azure Blob Manager demo!\");\r\n\r\n  console.log(\"Uploading sample file…\");\r\n  await blobService.uploadFile(CONTAINER_NAME, BLOB_NAME, sampleFile, {\r\n    contentType: \"text/plain\",\r\n    metadata: { createdBy: \"blob-manager-demo\", version: \"1\" },\r\n    tags: { environment: \"development\", project: \"blob-manager\" },\r\n  });\r\n  console.log(`✔ Uploaded \"${BLOB_NAME}\" with metadata and index tags.\\n`);\r\n\r\n  // 3. List blobs in the container\r\n  console.log(`Listing blobs in \"${CONTAINER_NAME}\":`);\r\n  const blobs = await blobService.listBlobs(CONTAINER_NAME);\r\n  for (const blob of blobs) {\r\n    console.log(`  • ${blob.name}  (size: ${blob.properties.contentLength} bytes)`);\r\n  }\r\n  console.log();\r\n\r\n  // 4. Download and print content\r\n  console.log(\"Downloading blob…\");\r\n  const downloaded = await blobService.download(CONTAINER_NAME, BLOB_NAME);\r\n  console.log(`✔ Downloaded ${downloaded.contentLength} bytes.`);\r\n  console.log(`  Content: \"${downloaded.content}\"`);\r\n  console.log(`  Metadata:`, downloaded.metadata);\r\n  console.log();\r\n\r\n  // 5. Overwrite the blob using a lease to prevent concurrent writes\r\n  console.log(\"Acquiring lease and overwriting blob…\");\r\n  await blobService.uploadWithLease(\r\n    CONTAINER_NAME,\r\n    BLOB_NAME,\r\n    \"Updated content — written under lease protection.\",\r\n    { contentType: \"text/plain\", metadata: { version: \"2\" } }\r\n  );\r\n  console.log(\"✔ Blob overwritten under lease.\\n\");\r\n\r\n  // Verify the update\r\n  const updated = await blobService.download(CONTAINER_NAME, BLOB_NAME);\r\n  console.log(`  Updated content: \"${updated.content}\"\\n`);\r\n\r\n  // 6. Delete the blob\r\n  console.log(\"Deleting blob…\");\r\n  await blobService.delete(CONTAINER_NAME, BLOB_NAME);\r\n  console.log(`✔ Blob \"${BLOB_NAME}\" deleted.\\n`);\r\n\r\n  // Clean up temp files\r\n  fs.unlinkSync(sampleFile);\r\n  fs.rmdirSync(sampleDir);\r\n\r\n  console.log(\"=== Demo complete ===\");\r\n}\r\n\r\nmain().catch((err) =\u003e {\r\n  console.error(\"Fatal error:\", err);\r\n  process.exit(1);\r\n});\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"lib\": [\"ES2020\"],\r\n    \"outDir\": \"dist\",\r\n    \"rootDir\": \"src\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"skipLibCheck\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"resolveJsonModule\": true,\r\n    \"declaration\": true,\r\n    \"declarationMap\": true,\r\n    \"sourceMap\": true\r\n  },\r\n  \"include\": [\"src/**/*\"],\r\n  \"exclude\": [\"node_modules\", \"dist\"]\r\n}\r\n\n```\n\n### package-lock.json\n```\n{\r\n  \"name\": \"azure-blob-manager\",\r\n  \"version\": \"1.0.0\",\r\n  \"lockfileVersion\": 3,\r\n  \"requires\": true,\r\n  \"packages\": {\r\n    \"\": {\r\n      \"name\": \"azure-blob-manager\",\r\n      \"version\": \"1.0.0\",\r\n      \"dependencies\": {\r\n        \"@azure/identity\": \"^4.6.0\",\r\n        \"@azure/storage-blob\": \"^12.26.0\"\r\n      },\r\n      \"devDependencies\": {\r\n        \"@types/node\": \"^22.15.3\",\r\n        \"typescript\": \"^5.8.3\"\r\n      }\r\n    },\r\n    \"node_modules/@azure/abort-controller\": {\r\n      \"version\": \"2.1.2\",\r\n      \"resolved\": \"https://registry.npmjs.org/@azure/abort-controller/-/abort-controller-2.1.2.tgz\",\r\n      